<script setup lang="ts">
import{ref,watch,onBeforeUnmount}from'vue';import{History,RefreshCw}from'@lucide/vue';
const props=defineProps<{taskId:string;version:number}>(),emit=defineEmits(['unauthorized']);
const expanded=ref(false),eventType=ref('all'),issueId=ref(''),issueTitle=ref(''),limit=ref(50),rows=ref<any[]>([]),people=ref<any[]>([]),next=ref<string|null>(null),total=ref(0),asOf=ref(''),loading=ref(false),loaded=ref(false),error=ref('');let generation=0,controller:AbortController|null=null;
const time=(s:any)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未登记',short=(id:any)=>id?String(id).slice(0,8).toUpperCase():'未登记',person=(id:any)=>id?(people.value.find(x=>x.id===id)?.name||'人员 '+short(id)):'尚未明确';
const types:any={arrangement:'安排保存 / 调整',contact:'实际联系登记',issue:'专业问题处理'},channels:any={phone:'电话',message:'消息',onsite:'当面',other:'其他'};
function clear(){generation++;controller?.abort();controller=null;rows.value=[];people.value=[];next.value=null;total.value=0;asOf.value='';loading.value=false;loaded.value=false;error.value='';}
watch(()=>[props.taskId,props.version],()=>{clear();expanded.value=false;issueId.value='';issueTitle.value='';eventType.value='all';});
async function load(more=false){if(loading.value)return;if(!more)clear();const gen=++generation;controller=new AbortController();const own=controller;loading.value=true;const query=new URLSearchParams({kind:'events',eventType:eventType.value,limit:String(limit.value)});if(issueId.value)query.set('issueId',issueId.value);if(more&&next.value)query.set('cursor',next.value);const timer=setTimeout(()=>own.abort(),12000);
 try{const r=await fetch(`/api/v1/followup/tasks/${props.taskId}/journal?${query}`,{credentials:'same-origin',signal:own.signal}),b=await r.json().catch(()=>({}));if(gen!==generation)return;if(!r.ok){if([401,403].includes(r.status)){clear();emit('unauthorized',r.status);return;}if(r.status===409){rows.value=[];people.value=[];next.value=null;loaded.value=false;}throw new Error(b.message||'无法读取办理经过。');}
  if(b.taskVersion!==props.version){clear();error.value='随访已有新的办理，请先刷新该随访，再查看完整经过。';return;}rows.value=more?[...rows.value,...b.items]:b.items;const names=new Map(people.value.map(p=>[p.id,p]));for(const p of b.people||[])names.set(p.id,p);people.value=[...names.values()];next.value=b.nextCursor;total.value=b.total;asOf.value=b.asOf;loaded.value=true;
 }catch(e){if(gen===generation)error.value=e instanceof Error&&e.name!=='AbortError'?e.message:'读取超时，请重新读取。';}finally{clearTimeout(timer);if(gen===generation){loading.value=false;controller=null;}}}
function toggle(){expanded.value=!expanded.value;if(expanded.value)load();else clear();}
function change(){clear();if(eventType.value!=='issue'){issueId.value='';issueTitle.value='';}if(expanded.value)load();}
function openIssue(id:string,title:string){clear();issueId.value=id;issueTitle.value=title;eventType.value='issue';expanded.value=true;load();}
function clearIssue(){clear();issueId.value='';issueTitle.value='';load();}
onBeforeUnmount(clear);defineExpose({openIssue});
</script>
<template><section class="b-card fu-journal"><header><div><h2><History :size="19"/>办理经过与问题追查</h2><p>从保存时的原始记录追查经过，不以当前结论覆盖过去。</p></div><button class="b-button outline small" :aria-expanded="expanded" @click="toggle">{{expanded?'收起办理经过':'查看办理经过'}}</button></header>
 <template v-if="expanded"><div class="fu-journal-controls"><label>办理类别<select aria-label="办理类别" v-model="eventType" @change="change"><option value="all">全部办理</option><option value="arrangement">安排保存 / 调整</option><option value="contact">实际联系登记</option><option value="issue">专业问题处理</option></select></label><label>历史每页项数<select aria-label="历史每页项数" v-model="limit" @change="change"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label><button class="b-button outline small" :disabled="loading" @click="load()"><RefreshCw :size="15"/>重新读取经过</button></div>
 <div v-if="issueId" class="fu-journal-focus">当前仅追查：{{issueTitle||('问题 '+short(issueId))}}<button class="f-text" @click="clearIssue">查看所有问题的处理</button></div>
 <p class="b-help">按操作登记时点倒序。人员标识来自原记录，辅助姓名来自当前员工目录；任务版本不是单项问题的版本号。临床记录仅显示引用标识。</p>
 <div v-if="error" class="b-alert error" role="alert">{{error}}</div><p v-if="loading" role="status">正在读取办理历史…</p><p v-if="loaded" class="b-help">已读取 {{rows.length}} / {{total}} 项 · 读取 {{time(asOf)}} · 当前任务版本 {{version}}</p><p v-if="loaded&&!rows.length" class="b-empty">尚无符合当前类别的后续办理记录；问题首次提出仍查看原联系记录。</p>
 <article v-for="r in rows" :key="r.id" class="fu-journal-event"><div class="fu-journal-meta"><strong>{{types[r.type]}}</strong><span>登记 {{time(r.savedAt)}}</span><span>{{r.editor.name}}</span></div><p class="b-help">操作 {{short(r.id)}} · 本次办理后任务版本 {{r.taskVersion??'未登记'}}</p><p v-if="r.reason">办理依据：{{r.reason}}</p>
  <template v-if="r.type==='arrangement'"><div class="fu-journal-comparison"><div v-for="(label,key) in {before:'保存前',after:'本次保存'}" :key="key"><h3>{{label}}</h3><template v-if="r[key]"><p>计划联系 {{time(r[key].planned_at)}}</p><p>负责人员 {{person(r[key].responsible_id)}}</p><p class="fu-journal-text">{{r[key].planned_content}}</p><p v-if="r[key].plan_version_id">方案 {{short(r[key].plan_version_id)}} · 节点 {{short(r[key].node_id)}}</p><p v-if="r[key].doctor_instruction" class="fu-journal-text">医生明确要求：{{r[key].doctor_instruction}}<br/>要求医生 {{person(r[key].instruction_doctor_id)}}</p><p>后续安排：{{r[key].next_action||'本版未登记'}}</p></template><p v-else>首次保存，此前没有已保存的安排。</p></div></div></template>
  <template v-if="r.type==='contact'"><p><strong>{{channels[r.contact.channel]||r.contact.channel}} · {{time(r.contact.contactedAt)}}</strong></p><span class="b-pill" :class="r.contact.reached?'active':''">{{r.contact.reached?'本次已联系到患者':'本次未联系到患者'}}</span><p class="fu-journal-text">{{r.contact.feedback}}</p><p>原后续安排：{{r.beforeNextAction||'未登记'}}</p><p>本次后续安排：{{r.contact.nextAction||'未登记'}}</p><p v-for="(p,n) in r.contact.problems" :key="n" class="fu-journal-text">当次提出问题：{{p.problem}} · 转交 {{person(p.doctorId)}}</p><p class="b-help">联系标识 {{short(r.contactId)}}；当次成功不代表专业问题已解决。</p></template>
  <template v-if="r.type==='issue'"><p class="fu-journal-text"><strong>{{r.after.problem}}</strong></p><div class="fu-journal-comparison"><div v-for="(label,key) in {before:'处理前',after:'本次核实登记'}" :key="key"><h3>{{label}}</h3><span class="b-pill" :class="r[key].resolved_at?'active':''">{{r[key].resolved_at?'已核实解决':'仍待医生处理'}}</span><p>接手医生 {{person(r[key].doctor_id)}}</p><p class="fu-journal-text">{{r[key].progress_conclusion||'尚无跟进结论'}}</p><p v-if="r[key].resolved_at">医生实际处理 {{time(r[key].resolved_at)}}</p><p v-if="r[key].clinical_basis" class="fu-journal-text">医生处理依据：{{r[key].clinical_basis}}</p><p>核实登记 {{person(r[key].recorded_by)}} · {{time(r[key].recorded_at)}}</p><p v-if="r[key].clinical_record_id" class="b-help">临床记录引用 {{short(r[key].clinical_record_id)}}</p></div></div><p class="b-help">问题 {{short(r.issueId)}} · 来源联系 {{short(r.after.source_contact_id)}}</p></template>
 </article><button v-if="next" class="b-button outline" :disabled="loading" @click="load(true)">读取更早办理</button></template>
</section></template>
<style scoped>
.fu-journal{padding:24px;min-width:0}.fu-journal>header,.fu-journal h2{display:flex;gap:10px;align-items:center}.fu-journal>header{justify-content:space-between;gap:20px}.fu-journal h2{font-size:18px;margin:0}.fu-journal header p{font-size:14px;color:#657b68;margin:8px 0;line-height:1.6}.fu-journal-controls{display:flex;align-items:end;gap:14px;flex-wrap:wrap;margin:20px 0}.fu-journal-controls label{display:grid;gap:8px;font-size:14px}.fu-journal-controls select{border:1px solid #d3dfd3;border-radius:7px;padding:10px;background:white;font:inherit}.fu-journal-focus{padding:12px 15px;background:#f0f6ed;font-size:14px;border-radius:8px;line-height:1.8}.fu-journal-focus button{display:block}.fu-journal-event{padding:20px;border:1px solid #dce5d7;border-radius:10px;margin:18px 0;font-size:15px;line-height:1.75;overflow-wrap:anywhere}.fu-journal-meta{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.fu-journal-meta strong{color:#285c3c}.fu-journal-event p{margin:9px 0}.fu-journal .b-help{font-size:13px;line-height:1.75}.fu-journal-comparison{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:16px 0}.fu-journal-comparison>div{background:#f6f8f3;border-radius:8px;padding:15px;min-width:0}.fu-journal-comparison h3{font-size:15px;margin:0 0 12px;color:#486240}.fu-journal-text{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:760px){.fu-journal{padding:16px}.fu-journal>header{align-items:flex-start;flex-wrap:wrap}.fu-journal-event{padding:15px}.fu-journal-comparison{grid-template-columns:1fr;gap:12px}.fu-journal-controls{gap:10px}.fu-journal-controls label{flex:1;min-width:120px}.fu-journal-controls select{width:100%}}
</style>
